  def __init__(self, f: Callable[[Value, Value], Value], x: SOp, y: SOp):
    super().__init__()
    self.f = f
    self.x = x
    self.y = y

  def __call__(self, xs: Sequence[Value]) -> Sequence[Value]:
    return [self.f(x, y) for x, y in zip(self.x(xs), self.y(xs))]

  @property
  def children(self) -> Sequence[RASPExpr]:
