class RASPExpr(Protocol):
  """A RASP expression."""

  def __call__(self, xs: Sequence[Value]) -> Value:
    """Evaluates this expression on the given input."""


def evaluate(expr: RASPExpr, xs: Sequence[Value]) -> Value:
  """Evaluates the given RASP expression on the given input."""
  if isinstance(expr, SOp):
    return _eval_sop(expr, xs)
  elif isinstance(expr, Selector):
    return _eval_selector(expr, xs)
  else:
    raise ValueError(f"Unknown expression type: {type(expr)}")


def _eval_sop(sop: SOp, xs: Sequence[Value]) -> Sequence[Value]:
  if isinstance(sop, TokensType):
    return list(xs)
  elif isinstance(sop, IndicesType):
    return list(range(len(xs)))
  elif isinstance(sop, LengthType):
    return [len(xs)] * len(xs)
  elif isinstance(sop, Map):
    inner = _eval_sop(sop.inner, xs)
    return [sop.f(x) for x in inner]
  elif isinstance(sop, SequenceMap):
    fst = _eval_sop(sop.fst, xs)
    snd = _eval_sop(sop.snd, xs)
    return [sop.f(x, y) for x, y in zip(fst, snd)]
  elif isinstance(sop, Full):
    return [sop.fill] * len(xs)
  elif isinstance(sop, ConstantSOp):
    if sop.check_length and len(sop.value) != len(xs):
      raise ValueError(
          f"ConstantSOp has length {len(sop.value)} but input has length "
          f"{len(xs)}")
    return list(sop.value)
  elif isinstance(sop, SelectorWidth):
    selector = _eval_selector(sop.selector, xs)
    return [sum(row) for row in selector]
  elif isinstance(sop, Aggregate):
    selector = _eval_selector(sop.selector, xs)
    values = _eval_sop(sop.sop, xs)
    result = []
    for i, row in enumerate(selector):
      agg = [values[j] for j, selected in enumerate(row) if selected]
      result.append(sum(agg) if agg else 0)
    return result
  else:
    raise ValueError(f"Unknown SOp type: {type(sop)}")


