def string_begins_with(prefix, str):
    return str.startswith(prefix)

def group_by_key_prefix(prefix, d):
    return group_dict_by_key(partial(string_begins_with, prefix), d)

def groupby_prefix_and_trim(prefix, d):
    kwargs_with_prefix, kwargs = group_dict_by_key(partial(string_begins_with, prefix), d)
    kwargs_without_prefix = dict(map(lambda x: (x[0][len(prefix):], x[1]), tuple(kwargs_with_prefix.items())))
    return kwargs_without_prefix, kwargs

def num_to_groups(num, divisor):
    groups = num // divisor
    remainder = num % divisor
    arr = [divisor] * groups
    if remainder > 0:
        arr.append(remainder)
    return arr

# url to fs, bucket, path - for checkpointing to cloud

def url_to_bucket(url):
    if '://' not in url:
        return url

    _, rest = url.split('://', 1)
    return rest.split('/')[0]

def split_by_slash(url):
    if '://' not in url:
        return url, ''

    _, rest = url.split('://', 1)
    return rest.split('/', 1)

def url_to_path(url):
    if '://' not in url:
        return url

    _, rest = url.split('://', 1)
    return rest

def is_local_path(url):
    return url.startswith('/') or url.startswith('./') or url.startswith('../') or '://' not in url

def get_fs_and_path(url):
    fs, path = url_to_fs(url)
    return fs, path

def save_checkpoint_to_path(path, obj):
    fs, path = url_to_fs(path)
    with fs.open(path, 'wb') as f:
        torch.save(obj, f)

def load_checkpoint_from_path(path):
    fs, path = url_to_fs(path)
    with fs.open(path, 'rb') as f:
        return torch.load(f, map_location='cpu')

