    def save(self):
        assert self.can_checkpoint, 'you cannot save on this process'

        if not exists(self.checkpoint_path):
            return

        self.accelerator.wait_for_everyone()

        save_obj = {
            'model': self.imagen.state_dict(),
            'steps': self.steps.cpu(),
        }

        save_obj['optim'] = []
        save_obj['scaler'] = []
        save_obj['scheduler'] = []
        save_obj['warmup'] = []

        for ind in range(self.num_unets):
            optim = getattr(self, f'optim{ind}')
            scaler = getattr(self, f'scaler{ind}')
            scheduler = getattr(self, f'scheduler{ind}')
            warmup_scheduler = getattr(self, f'warmup{ind}')

            save_obj['optim'].append(optim.state_dict())
            save_obj['scaler'].append(scaler.state_dict())
            save_obj['scheduler'].append(scheduler.state_dict() if exists(scheduler) else None)
            save_obj['warmup'].append(warmup_scheduler.state_dict() if exists(warmup_scheduler) else None)

        if self.use_ema:
            save_obj['ema_model'] = self.ema_unets.state_dict()

        save_obj = self.accelerator.get_state_dict(save_obj)

        self.fs.mkdirs(self.checkpoint_path, exist_ok = True)

        save_path = os.path.join(self.checkpoint_path, f'checkpoint.{self.steps.max().item()}.pt')
        torch.save(save_obj, save_path)

