    def cleanup_checkpoints(self):
        if not exists(self.max_checkpoints_keep):
            return

        checkpoints = self.fs.ls(self.checkpoint_path)
        checkpoints = [c for c in checkpoints if c.endswith('.pt')]

        if len(checkpoints) <= self.max_checkpoints_keep:
            return

        checkpoints = sorted(checkpoints, key = lambda c: int(c.split('.')[-2]))

        for c in checkpoints[:-self.max_checkpoints_keep]:
            self.fs.rm(c)

