            scheduler = getattr(self, f'scheduler{ind}')
            warmup_scheduler = getattr(self, f'warmup{ind}')

            optim.load_state_dict(save_obj['optim'][ind])
            scaler.load_state_dict(save_obj['scaler'][ind])

            if exists(scheduler) and exists(save_obj['scheduler'][ind]):
                scheduler.load_state_dict(save_obj['scheduler'][ind])

            if exists(warmup_scheduler) and exists(save_obj['warmup'][ind]):
                warmup_scheduler.load_state_dict(save_obj['warmup'][ind])

