class Map(SOp):
  """A Sequence Map operation."""

  def __init__(self, f: Callable[[Value], Value], inner: SOp):
    super().__init__()
    self.f = f
    self.inner = inner

  @property
  def children(self) -> Sequence[RASPExpr]:
    return [self.inner]

  @property
  def name(self) -> str:
    return "map"

  def __call__(self, xs: Sequence[Value]) -> Sequence[Value]:
    return [self.f(x) for x in self.inner(xs)]


class SequenceMap(SOp):
  """A Sequence Map operation over two sequences."""

  def __init__(self, f: Callable[[Value, Value], Value], inner1: SOp,
               inner2: SOp):
    super().__init__()
    self.f = f
    self.inner1 = inner1
    self.inner2 = inner2

  @property
  def children(self) -> Sequence[RASPExpr]:
    return [self.inner1, self.inner2]

  @property
  def name(self) -> str:
    return "seq_map"

  def __call__(self, xs: Sequence[Value]) -> Sequence[Value]:
    return [self.f(x, y) for x, y in zip(self.inner1(xs), self.inner2(xs))]


class Select(SOp):
  """A Select operation."""

  def __init__(self, keys: SOp, queries: SOp, predicate: Callable[[Value, Value],
                                                                  bool]):
    super().__init__()
    self.keys = keys
    self.queries = queries
    self.predicate = predicate

  @property
  def children(self) -> Sequence[RASPExpr]:
    return [self.keys, self.queries]

  @property
  def name(self) -> str:
    return "select"

  def __call__(self, xs: Sequence[Value]) -> Sequence[Value]:
    keys = self.keys(xs)
    queries = self.queries(xs)
    return [
        next((k for k, q in zip(keys, queries) if self.predicate(k, q)), None)
        for _ in xs
    ]


class Aggregate(SOp):
  """An Aggregate operation."""

  def __init__(self, inner: SOp, f: Callable[[Sequence[Value]], Value]):
    super().__init__()
    self.inner = inner
    self.f = f

  @property
  def children(self) -> Sequence[RASPExpr]:
    return [self.inner]

  @property
  def name(self) -> str:
    return "aggregate"

  def __call__(self, xs: Sequence[Value]) -> Sequence[Value]:
    return [self.f(self.inner(xs))] * len(xs)


class SelectorWidth(SOp):
  """A Selector Width operation."""

  def __init__(self, selector: SOp):
    super().__init__()
    self.selector = selector

  @property
  def children(self) -> Sequence[RASPExpr]:
    return [self.selector]

  @property
  def name(self) -> str:
    return "selector_width"

  def __call__(self, xs: Sequence[Value]) -> Sequence[Value]:
    selector = self.selector(xs)
    return [sum(1 for s in selector if s == i) for i in range(len(xs))]

