def make_sort_unique(vals: rasp.SOp, keys: rasp.SOp) -> rasp.SOp:
  """Returns argsort of `vals` by descending `keys`."""
  select_all = rasp.Select(rasp.indices, rasp.indices,
                           rasp.Comparison.TRUE).named("select_all")
  select_prev = rasp.Select(keys, keys,
                            rasp.Comparison.LEQ).named("select_prev")
  return rasp.Aggregate(select_prev, vals, default=0).named("sort_unique")


def make_sort(vals: rasp.SOp, keys: rasp.SOp, max_seq_len: int) -> rasp.SOp:
  """Returns the values sorted by keys in ascending order."""
  sort_unique = make_sort_unique(vals, keys)
  select_all = rasp.Select(rasp.indices, rasp.indices,
                           rasp.Comparison.TRUE).named("select_all")
  return rasp.Aggregate(select_all, sort_unique).named("sort")


def make_count_less_freq(n: int) -> rasp.SOp:
  """Returns how many tokens appear fewer than n times in the input.

  The output sequence contains this count in each position.

  Example usage:
    count_less = make_count_less_freq(2)
    count_less("aaaabcc")
    >> [2, 2, 2, 2, 2, 2, 2]

  Args:
    n: Integer to compare token frequences to.
  """
  hist = make_hist()
  bools = hist < n
  # Keep only one token per distinct token, using a select-and-aggregate.
  select_all = rasp.Select(rasp.indices, rasp.indices,
                           rasp.Comparison.TRUE).named("select_all")
  return rasp.numerical(rasp.Aggregate(select_all, bools,
                                       default=0)).named("count_less_freq")


def make_count_less_freq2() -> rasp.SOp:
  return make_count_less_freq(n=2).named("count_less_freq2")


def make_shifted_tokens(shift: int) -> rasp.SOp:
  """Returns the tokens shifted by `shift` positions."""
  opp_idx = (rasp.indices + shift).named("opp_idx")
  select = rasp.Select(opp_idx, rasp.indices,
                       rasp.Comparison.EQ).named("select")
  return rasp.Aggregate(select, rasp.tokens).named("shifted_tokens")


def make_shifted_tokens2() -> rasp.SOp:
  return make_shifted_tokens(shift=1).named("shifted_tokens2")


def make_most_frequent() -> rasp.SOp:
  """Returns the most frequent token in the input.

  Example usage:
    most_frequent = make_most_frequent()
    most_frequent("aabbbcc")
    >> ['b', 'b', 'b', 'b', 'b', 'b', 'b']
  """
  hist = make_hist()
  select_all = rasp.Select(rasp.indices, rasp.indices,
                           rasp.Comparison.TRUE).named("select_all")
  max_hist = rasp.Aggregate(select_all, hist, default=0).named("max_hist")
  select_max = rasp.Select(hist, max_hist,
                           rasp.Comparison.EQ).named("select_max")
  return rasp.Aggregate(select_max, rasp.tokens).named("most_frequent")


def make_most_frequent2() -> rasp.SOp:
  return make_most_frequent().named("most_frequent2")


def make_frac_prevs(bools: rasp.SOp) -> rasp.SOp:
  """Count the fraction of previous tokens.

  Example usage:
    num_l = make_frac_prevs(rasp.tokens == "l")
    num_l("hello")
    >> [0, 0, 0, 1/3, 1/4]

  Args:
    bools: SOp mapping a sequence to a sequence of booleans.

  Returns:
    frac_prevs: SOp mapping an input to a sequence, where every element
      is the fraction of previous tokens where `bools` was True.
  """
  bools = rasp.numerical(bools).named("bools")
  select_all = rasp.Select(rasp.indices, rasp.indices,
                           rasp.Comparison.TRUE).named("select_all")
  cumsum = rasp.Aggregate(select_all, bools).named("cumsum")
  length = make_length()
  return (cumsum / length).named("frac_prevs")


