def cosine_beta_schedule(timesteps, s = 0.008):
    """
    cosine schedule
    as proposed in https://openreview.net/forum?id=-NEXDKk8gZ
    """
    steps = timesteps + 1
    x = torch.linspace(0, timesteps, steps, dtype = torch.float64)
    alphas_cumprod = torch.cos(((x / timesteps) + s) / (1 + s) * math.pi * 0.5) ** 2
    alphas_cumprod = alphas_cumprod / first(alphas_cumprod)
    betas = 1 - (alphas_cumprod[1:] / alphas_cumprod[:-1])
    return torch.clip(betas, 0, 0.999)

class NoiseSchedule(nn.Module):
    def __init__(
        self,
        *,
        timesteps = 1000,
        schedule = 'cosine',
        init_zero = False,
        learned = False
    ):
        super().__init__()
        assert schedule in ('cosine', 'linear')

        if schedule == 'cosine':
            self.register_buffer('betas', cosine_beta_schedule(timesteps), persistent = False)
        elif schedule == 'linear':
            self.register_buffer('betas', torch.linspace(0.0001, 0.02, timesteps), persistent = False)

        alphas = 1. - self.betas
        alphas_cumprod = torch.cumprod(alphas, axis = 0)
        alphas_cumprod_prev = F.pad(alphas_cumprod[:-1], (1, 0), value = 1.)

        self.register_buffer('alphas_cumprod', alphas_cumprod, persistent = False)
        self.register_buffer('alphas_cumprod_prev', alphas_cumprod_prev, persistent = False)
        self.register_buffer('sqrt_alphas_cumprod', torch.sqrt(alphas_cumprod), persistent = False)
        self.register_buffer('sqrt_one_minus_alphas_cumprod', torch.sqrt(1. - alphas_cumprod), persistent = False)
        self.register_buffer('log_one_minus_alphas_cumprod', torch.log(1. - alphas_cumprod), persistent = False)
        self.register_buffer('sqrt_recip_alphas_cumprod', torch.sqrt(1. / alphas_cumprod), persistent = False)
        self.register_buffer('sqrt_recipm1_alphas_cumprod', torch.sqrt(1. / alphas_cumprod - 1), persistent = False)

        posterior_variance = self.betas * (1. - alphas_cumprod_prev) / (1. - alphas_cumprod)
        self.register_buffer('posterior_variance', posterior_variance, persistent = False)
        self.register_buffer('posterior_log_variance_clipped', torch.log(posterior_variance.clamp(min = 1e-20)), persistent = False)
        self.register_buffer('posterior_mean_coef1', self.betas * torch.sqrt(alphas_cumprod_prev) / (1. - alphas_cumprod), persistent = False)
        self.register_buffer('posterior_mean_coef2', (1. - alphas_cumprod_prev) * torch.sqrt(alphas) / (1. - alphas_cumprod), persistent = False)

