        optimizers = []

        for unet_number, unet in enumerate(self.imagen.unets):
            if exists(self.only_train_unet_number) and self.only_train_unet_number != unet_number:
                optimizers.append(None)
                continue

            if self.use_lion:
                optimizer = Lion(
                    unet.parameters(),
                    lr = self.lr,
                    weight_decay = self.weight_decay
                )
            else:
                optimizer = Adam(
                    unet.parameters(),
                    lr = self.lr,
                    betas = self.betas,
                    eps = self.eps,
                    weight_decay = self.weight_decay
                )

            optimizers.append(optimizer)

        return optimizers

