    def train_step(self, unet_number = None, **kwargs):
        unet_number = self.validate_unet_number(unet_number)
        unet_index = unet_number - 1

        self.validate_and_set_unet_being_trained(unet_number)

        unet = self.unet_being_trained
        optim = getattr(self, f'optim{unet_index}')
        scaler = getattr(self, f'scaler{unet_index}')
        scheduler = getattr(self, f'scheduler{unet_index}')
        warmup_scheduler = getattr(self, f'warmup{unet_index}')

        if self.is_distributed:
            unet = self.accelerator.unwrap_model(unet)

        unet.train()

        if self.use_ema:
            ema_unet = self.ema_unets[unet_index]
            ema_unet.train()

        self.imagen.train()

        batch = self.next_dataloader()

        if isinstance(batch, dict):
            batch = {k: v for k, v in batch.items() if k in self.dl_tuple_output_keywords_names}

        if self.cast_half_at_training:
            batch = cast_to_half(batch)

        with self.accelerator.accumulate(unet):
            with self.accelerator.autocast():
                loss = self.imagen(batch, unet_number = unet_number, **kwargs)

            self.accelerator.backward(loss)

            if exists(self.max_grad_norm):
                self.accelerator.clip_grad_norm_(unet.parameters(), self.max_grad_norm)

            optim.step()
            optim.zero_grad()

            if exists(scheduler):
                scheduler.step()

            if exists(warmup_scheduler):
                warmup_scheduler.step()

        if self.use_ema:
            ema_unet.update()

        self.steps[unet_index] += 1

        return loss

