    def load_from_checkpoint_folder(self, last_total_steps = -1):
        if last_total_steps != -1:
            filepath = self.checkpoint_path + f'/model-{last_total_steps}.pt'
            self.load(filepath)
            return

        import re

        files = [f for f in self.fs.ls(self.checkpoint_path) if f.endswith('.pt')]

        if len(files) == 0:
            return

        def get_total_steps(filename):
            match = re.search(r'model-(\d+).pt', filename)
            if not exists(match):
                return -1
            return int(match.group(1))

        files_with_steps = [(f, get_total_steps(f)) for f in files]
        files_with_steps = [(f, steps) for f, steps in files_with_steps if steps != -1]

        if len(files_with_steps) == 0:
            return

        files_with_steps.sort(key = lambda t: t[1])
        most_recent_file, total_steps = files_with_steps[-1]

        self.load(most_recent_file)

