def load(self, path, strict = True):
    # returning bool makes it easier to use with `maybe`

    path = Path(path)
    assert path.is_file()

    self.print(f'loading model from {str(path)}')

    loaded_obj = torch.load(str(path), map_location = self.device)

    if 'version' in loaded_obj:
        assert loaded_obj['version'] == __version__, f'you are trying to load a model saved with version {loaded_obj["version"]}, but you are on version {__version__}'

    self.unwrapped_imagen.load_state_dict(loaded_obj['model'], strict = strict)

    if self.use_ema and 'ema_model' in loaded_obj:
        self.unwrapped_ema_unets.load_state_dict(loaded_obj['ema_model'], strict = strict)

    return True

def load_from_checkpoint_folder(self, last_total_steps = -1):
    if last_total_steps != -1:
        filepath = self.checkpoint_path / f'checkpoint.{last_total_steps}.pt'
        self.load(filepath)
        return

    sorted_checkpoints = self.all_checkpoints_are_equivalent()

    if len(sorted_checkpoints) == 0:
        self.print(f'no checkpoints to load from folder {str(self.checkpoint_path)}')
        return

    last_checkpoint = sorted_checkpoints[-1]
    self.load(last_checkpoint)

def all_checkpoints_are_equivalent(self):
    self.print(f'loading checkpoints from folder {str(self.checkpoint_path)}')

    sorted_checkpoints = sorted(self.checkpoint_path.glob('checkpoint.*.pt'), key = lambda p: int(p.stem.split('.')[1]))

    if len(sorted_checkpoints) == 0:
        self.print(f'no checkpoints to load from folder {str(self.checkpoint_path)}')
        return []

    return sorted_checkpoints

def save_to_checkpoint_folder(self):
    self.print(f'saving to folder {str(self.checkpoint_path)}')

    save_num = 0
    while (self.checkpoint_path / f'checkpoint.{save_num}.pt').exists():
        save_num += 1

    self.save(self.checkpoint_path / f'checkpoint.{save_num}.pt')

    # remove old checkpoints

    sorted_checkpoints = sorted(self.checkpoint_path.glob('checkpoint.*.pt'), key = lambda p: int(p.stem.split('.')[1]))

    if len(sorted_checkpoints) > self.max_checkpoints_keep:
        for checkpoint in sorted_checkpoints[:-self.max_checkpoints_keep]:
            checkpoint.unlink()

