        unwrapped_imagen.save(path, overwrite = overwrite)
        self.save_checkpoint(path)

    def load(self, path, only_model = False, strict = True, **kwargs):
        path = Path(path)

        self.accelerator.wait_for_everyone()

        self.imagen.load(path, only_model = only_model, strict = strict, **kwargs)
        self.load_checkpoint(path, strict = strict)

    @property
    def state_dict(self):
        return self.accelerator.get_state_dict(self.imagen)

    @property
    def optimizers(self):
        return self.accelerator._optimizers

    @property
    def scalers(self):
        if not hasattr(self, 'scaler0'):
            return []

        return [getattr(self, f'scaler{i}') for i in range(self.num_unets)]

    @property
    def has_optimizers(self):
        return len(self.optimizers) > 0

    @property
    def has_scalers(self):
        return len(self.scalers) > 0

    def save_checkpoint(self, path, **kwargs):
        if not self.is_main:
            return

        save_obj = dict(
            model = self.imagen.state_dict(),
            version = __version__,
            steps = self.steps.cpu(),
        )

        save_obj = {**save_obj, **kwargs}

        for ind in range(0, self.num_unets):
            scaler = getattr(self, f'scaler{ind}', None)
            optimizer = getattr(self, f'optim{ind}', None)
            scheduler = getattr(self, f'scheduler{ind}', None)

            if exists(scaler):
                save_obj = {**save_obj, **{f'scaler{ind}': scaler.state_dict()}}

            if exists(optimizer):
                save_obj = {**save_obj, **{f'optim{ind}': optimizer.state_dict()}}

            if exists(scheduler):
                save_obj = {**save_obj, **{f'scheduler{ind}': scheduler.state_dict()}}

        path = Path(path)
        path.parent.mkdir(exist_ok = True, parents = True)

        torch.save(save_obj, str(path))

    def load_checkpoint(self, path, strict = True):
        path = Path(path)
        assert path.exists()

        if not self.is_main:
            return

        loaded_obj = torch.load(str(path), map_location='cpu')

        if version.parse(__version__) != version.parse(loaded_obj['version']):
            self.print(f'loading saved imagen at version {loaded_obj["version"]}, but current package version is {__version__}')

        try:
            self.imagen.load_state_dict(loaded_obj['model'], strict = strict)
        except RuntimeError:
            self.print('failed loading model')

        if exists(loaded_obj.get('steps')):
            self.steps.copy_(loaded_obj['steps'])

        for ind in range(0, self.num_unets):
            scaler = getattr(self, f'scaler{ind}', None)
            optimizer = getattr(self, f'optim{ind}', None)
            scheduler = getattr(self, f'scheduler{ind}', None)

            if exists(scaler):
                try:
                    scaler_state_dict = loaded_obj[f'scaler{ind}']
                    scaler.load_state_dict(scaler_state_dict)
                except:
                    self.print(f'failed loading scaler at unet {ind + 1}')

            if exists(optimizer):
                try:
                    optimizer_state_dict = loaded_obj[f'optim{ind}']
                    optimizer.load_state_dict(optimizer_state_dict)
                except:
                    self.print(f'failed loading optimizer at unet {ind + 1}')

            if exists(scheduler):
                try:
                    scheduler_state_dict = loaded_obj[f'scheduler{ind}']
                    scheduler.load_state_dict(scheduler_state_dict)
                except:
                    self.print(f'failed loading scheduler at unet {ind + 1}')

        return loaded_obj

