    def load_from_checkpoint_folder(self, last_total_steps = -1):
        if last_total_steps != -1:
            file_prefix = f'{last_total_steps}'
        else:
            file_prefix = ''

        path = self.checkpoint_path
        files = [f for f in self.fs.ls(path) if f.startswith(file_prefix)]
        files = sorted(files)

        for filename in files:
            try:
                self.load_checkpoint(filename)
                self.print(f'loaded from checkpoint: {filename}')
            except Exception as e:
                self.print(f'failed loading checkpoint: {filename}')

    def save_on_checkpoint(self, unet_number = None, force = False):
        if not self.checkpointing_enabled:
            return

        if not force and not self.should_checkpoint():
            return

        self.checkpoint_num += 1
        checkpoint_path = self.checkpoint_path

        if not exists(checkpoint_path):
            return

        if not self.is_main:
            return

        self.print(f'saving checkpoint {self.checkpoint_num} - {self.num_steps_taken(unet_number)}')

        self.save_checkpoint(checkpoint_path)

    def should_checkpoint(self):
        needs_checkpoint = False

        for scheduler in self.schedulers:
            if exists(scheduler) and scheduler.checkpoint_should_save:
                scheduler.checkpoint_should_save = False
                needs_checkpoint = True

        return needs_checkpoint

    @property
    def schedulers(self):
        return [getattr(self, f'scheduler{i}', None) for i in range(self.num_unets)]

    @property
    def checkpoint_path(self):
        if not self.checkpointing_enabled:
