def _annotate_encoding(
    sop: SOp,
    encoding: Optional[Encoding] = None,
) -> SOp:
  """Annotates a SOp with an encoding, and recursively annotates children."""
  if encoding is not None:
    sop.annotations["encoding"] = encoding
  for child in sop.children:
    if isinstance(child, SOp):
      _annotate_encoding(child, encoding)
  return sop


