def make_length() -> rasp.SOp:
  """Returns the length of the input sequence."""
  return rasp.SelectorWidth(
      rasp.Select(rasp.indices, rasp.indices,
                  rasp.Comparison.TRUE)).named("length")


def make_reverse(sop: rasp.SOp) -> rasp.SOp:
  """Returns the sop, reversed."""
  length = make_length()
  reverse_pos = length - 1 - rasp.indices
  sel_rev = rasp.Select(rasp.indices, reverse_pos, rasp.Comparison.EQ)
  return rasp.Aggregate(sel_rev, sop).named("reverse")


def make_prev(sop: rasp.SOp) -> rasp.SOp:
  """Returns the sop, shifted by 1, None-padded."""
  return shift_by(-1, sop).named("prev")


def make_next(sop: rasp.SOp) -> rasp.SOp:
  """Returns the sop, shifted by 1, None-padded."""
  return shift_by(1, sop).named("next")

