class MLP(Block):
  """A transformer MLP."""
  fst: vectorspace_fns.Linear
  snd: vectorspace_fns.Linear
  residual_space: Optional[bases.VectorSpaceWithBasis] = None

  def __post_init__(self):
    """Infer residual stream and typecheck subspaces."""
    if self.residual_space is None:
      self.residual_space = bases.VectorSpaceWithBasis(
          self.fst.input_space.basis + self.snd.output_space.basis)
    else:
      assert self.fst.input_space <= self.residual_space
      assert self.snd.output_space <= self.residual_space

  def apply(self, x: bases.VectorInBasis) -> bases.VectorInBasis:
    assert x in self.residual_space
    # seq_len x hidden_space
    hidden = x.project(self.fst.input_space)
    hidden = bases.VectorInBasis(
        self.fst.output_space.basis, hidden.magnitudes @ self.fst.matrix)
    hidden = relu(hidden)
    # seq_len x output_space
    out = hidden.magnitudes @ self.snd.matrix
    return bases.VectorInBasis(self.snd.output_space.basis, out)


@dataclasses.dataclass
class ResidualStream(Block):
  """A residual stream, i.e. a sequence of blocks applied in order."""
  blocks: Sequence[Block]
  residual_space: Optional[bases.VectorSpaceWithBasis] = None

  def __post_init__(self):
    """Infer residual stream and typecheck subspaces."""
    if self.residual_space is None:
      self.residual_space = bases.VectorSpaceWithBasis(
          [d for block in self.blocks for d in block.residual_space.basis])
    else:
      for block in self.blocks:
        assert block.residual_space <= self.residual_space

  def apply(self, x: bases.VectorInBasis) -> bases.VectorInBasis:
    assert x in self.residual_space
    for block in self.blocks:
      x = x + block.apply(x)
    return x


