        for input_key, sample_elem in sample.items():
            self.input_key = input_key
            args = self.trunk_field_args.get(input_key, [])
            kwargs = self.trunk_field_kwargs.get(input_key, {})
            args = [getattr(sample_elem, arg) for arg in args]
