                for k, v in self.trunk_field_kwargs[None].items()
            }
        else:
            args = []
            kwargs = {}
        return args, kwargs

    def forward(self, sample: Mapping[str, VisionSample]):
        if self.handle_list_inputs:
            return self._forward_list_inputs(sample)
        else:
            return self._forward(sample)

    def _forward(self, sample: Mapping[str, VisionSample]):
        self.outputs = {}
        for input_key, input_sample in sample.items():
            self.input_key = input_key
            self.sample = input_sample
            args, kwargs = self._get_trunk_fields()
            self.trunk(input_sample, *args, **kwargs)
        outputs = self.outputs
        self.outputs = {}
        self.input_key = None
        return outputs

    def _forward_list_inputs(self, sample: Mapping[str, Sequence[VisionSample]]):
        self.outputs = {}
        for input_key, input_samples in sample.items():
            self.input_key = input_key
            for input_sample in input_samples:
                self.sample = input_sample
                args, kwargs = self._get_trunk_fields()
                self.trunk(input_sample, *args, **kwargs)
        outputs = self.outputs
        self.outputs = {}
        self.input_key = None
        return outputs

    def __del__(self):
        for hook_handle in self.hook_handles:
            hook_handle.remove()

