      m = (p_pdf + q_pdf) / 2
      return (stats.entropy(p_pdf, m) + stats.entropy(q_pdf, m)) / 2
  elif method == "min":
    if discrete:
      x = jnp.unique(jnp.concatenate([p, q]))
      p_pmf = _pmf(p, x)
      q_pmf = _pmf(q, x)
      return jnp.minimum(p_pmf, q_pmf).sum()
