class Collator:
    def __init__(self, image_size, url_label, text_label, image_label, name, channels):
        self.url_label = url_label
        self.text_label = text_label
        self.image_label = image_label
        self.download = url_label is not None
        self.name = name
        self.channels = channels
        self.transform = T.Compose([
            T.Resize(image_size),
            T.CenterCrop(image_size),
            T.ToTensor(),
        ])
    def __call__(self, batch):

        texts = []
        images = []
        for item in batch:
            try:
                if self.download:
                    image = self.fetch_image(item[self.url_label])
                else:
                    image = item[self.image_label]

                image = convert_image_to('RGB', image)
                image = self.transform(image)

                if self.channels == 1:
                    image = image.mean(dim = 0, keepdim = True)

                images.append(image)

                text = item[self.text_label]
                if isinstance(text, list):
                    text = random.choice(text)

                texts.append(text)
            except (Exception, OSError) as e:
                continue

        images = torch.stack(images)
        return images, texts

    def fetch_image(self, url):
        image = None
        try:
            request = urllib.request.Request(
                url,
                data = None,
                headers = {"user-agent": USER_AGENT}
            )
            with urllib.request.urlopen(request) as resp:
                image = Image.open(io.BytesIO(resp.read()))
        except (Exception, OSError) as e:
            pass
        return image

