    videos,
    downsample_scale = 1,
    mode = 'nearest'
):
    if downsample_scale == 1:
        return videos

    image_size = videos.shape[-1]
    needs_resize = videos.shape[-3] % downsample_scale != 0

    if not needs_resize:
        return videos

    frame_dims = videos.shape[-3]
    new_frame_dims = frame_dims // downsample_scale

    videos = rearrange(videos, 'b c f h w -> (b f) c h w')
    videos = F.interpolate(videos, size = (image_size, image_size), mode = mode)
    videos = rearrange(videos, '(b f) c h w -> b c f h w', f = new_frame_dims)

    return videos

