def resize_image_to(image, target_image_size, clamp_range = None):
    orig_image_size = image.shape[-1]

    if orig_image_size == target_image_size:
        return image

    scale_factors = target_image_size / orig_image_size
    out = F.interpolate(image, scale_factor = scale_factors, mode = 'nearest')

    if not exists(clamp_range):
        return out

    return out.clamp(*clamp_range)

def calc_all_frame_dims(
    downsample_factors,
    image_size,
    temporal_downsample_factor = 1,
    video_frames = 1
):
    if not exists(downsample_factors):
        return []

    if isinstance(downsample_factors, int):
        downsample_factors = (downsample_factors,) * len(downsample_factors)

    assert len(downsample_factors) == len(image_size), 'downsample factors must match dimensions of image size'

    frame_dims = []
    curr_image_size = image_size

    for downsample_factor in downsample_factors:
        curr_image_size = tuple(map(lambda t: t // downsample_factor, curr_image_size))
        frame_dims.append(curr_image_size)

    if temporal_downsample_factor > 1:
        video_frames = video_frames // temporal_downsample_factor

    return frame_dims

