def save(self, path, overwrite = True):
    assert self.is_main

    if not overwrite and self.fs.exists(path):
        return

    self.fs.makedirs(path, exist_ok = True)

    save_obj = {
        'version': __version__,
        'steps': self.steps.cpu(),
        'imagen': self.unwrapped_imagen.state_dict(),
        'ema_unets': self.unwrapped_ema_unets.state_dict() if self.use_ema else None,
    }

    for ind in range(self.num_unets):
        save_obj[f'optim{ind}'] = getattr(self, f'optim{ind}').state_dict()
        save_obj[f'scaler{ind}'] = getattr(self, f'scaler{ind}').state_dict()
        save_obj[f'scheduler{ind}'] = getattr(self, f'scheduler{ind}').state_dict() if exists(getattr(self, f'scheduler{ind}')) else None
        save_obj[f'warmup{ind}'] = getattr(self, f'warmup{ind}').state_dict() if exists(getattr(self, f'warmup{ind}')) else None

    with self.fs.open(path + '/model.pt', 'wb') as f:
        torch.save(save_obj, f)

