    self.unwrapped_imagen.load_state_dict(load_obj['imagen'])

    if self.use_ema and exists(load_obj['ema_unets']):
        self.unwrapped_ema_unets.load_state_dict(load_obj['ema_unets'])

    for ind in range(self.num_unets):
        getattr(self, f'optim{ind}').load_state_dict(load_obj[f'optim{ind}'])
        getattr(self, f'scaler{ind}').load_state_dict(load_obj[f'scaler{ind}'])

        if exists(load_obj[f'scheduler{ind}']) and exists(getattr(self, f'scheduler{ind}')):
            getattr(self, f'scheduler{ind}').load_state_dict(load_obj[f'scheduler{ind}'])

