class DatasetFromDataLoader(torch.utils.data.Dataset):
    def __init__(self, dataloader):
        self.dataloader = dataloader
        self._iterator = None

    def __getitem__(self, ind):
        if not exists(self._iterator):
            self._iterator = iter(self.dataloader)

        try:
            return next(self._iterator)
        except StopIteration:
            self._iterator = iter(self.dataloader)
            return next(self._iterator)

    def __len__(self):
        return len(self.dataloader)

# main trainer class

class ImagenTrainer(nn.Module):
    def __init__(
        self,
        imagen,
        use_ema = True,
        ema_decay = 0.995,
        ema_update_after_step = 1000,
        ema_update_every = 10,
        warmup_steps = 0,
        cosine_decay_max_steps = None,
        only_train_unet_number = None,
        **kwargs
    ):
        super().__init__()
        self.accelerator = Accelerator(
            split_batches = False,
            gradient_accumulation_steps = 1,
            kwargs_handlers = [DistributedDataParallelKwargs(find_unused_parameters = True)]
        )

        self.imagen = imagen
        self.ema_imagen = EMA(
            imagen,
            beta = ema_decay,
            update_after_step = ema_update_after_step,
            update_every = ema_update_every
        ) if use_ema else None

        self.ema_imagen.to(self.device)

        self.warmup_steps = warmup_steps
        self.cosine_decay_max_steps = cosine_decay_max_steps

        self.only_train_unet_number = only_train_unet_number

        self.accelerator.wait_for_everyone()

        self.is_main = self.accelerator.is_local_main_process
        self.is_local_main = self.accelerator.is_local_main_process
        self.is_global_main = self.accelerator.is_main_process

        self.unet_being_trained_index = -1
        self.all_unet_being_trained = []

        self.register_buffer('steps', torch.Tensor([0]))

        self.imagen.to(self.device)

        self.optimizers = []

        for unet_number, unet in enumerate(imagen.unets):
            optimizer = Adam(unet.parameters(), lr = 1e-4)
            self.optimizers.append(optimizer)

        self.scheduler = None
        self.warmup_scheduler = None

        self.grad_scaler = GradScaler(enabled = False)

        self.dl = None
        self.dl_iter = None

        self.ema_imagen.to(self.device)

    @property
    def device(self):
        return self.accelerator.device

    @property
    def is_distributed(self):
        return not (self.accelerator.distributed_type == DistributedType.NO)

    @property
    def unet(self):
        unet = self.imagen.unets[self.unet_being_trained_index]
        return self.accelerator.unwrap_model(unet)

    @property
    def unets(self):
        return nn.ModuleList([self.accelerator.unwrap_model(unet) for unet in self.imagen.unets])

    @property
