    # training related functions - gradient accumulation, gradient clipping

    def set_lr(self, unet_number, lr):
        self.validate_unet_number(unet_number)
        unet_index = unet_number - 1

        optim = getattr(self, f'optim{unet_index}')
        scheduler = getattr(self, f'scheduler{unet_index}')

        for param_group in optim.param_groups:
            param_group['lr'] = lr

        if exists(scheduler):
            scheduler.base_lrs = [lr] * len(scheduler.base_lrs)

    def zero_grad(self, unet_number):
        self.validate_unet_number(unet_number)
        unet_index = unet_number - 1

        optim = getattr(self, f'optim{unet_index}')
        optim.zero_grad()

    def step(self, unet_number, grad_scaler_enabled = True):
        self.validate_unet_number(unet_number)
        unet_index = unet_number - 1

        optim = getattr(self, f'optim{unet_index}')
        scaler = getattr(self, f'scaler{unet_index}')
        scheduler = getattr(self, f'scheduler{unet_index}')
        warmup_scheduler = getattr(self, f'warmup{unet_index}')

        if self.max_grad_norm is not None:
            self.accelerator.clip_grad_norm_(self.unet_being_trained.parameters(), self.max_grad_norm)

        if grad_scaler_enabled:
            scaler.step(optim)
            scaler.update()
        else:
            optim.step()

        if exists(warmup_scheduler):
            warmup_scheduler.step()

        if exists(scheduler):
            scheduler.step()

        self.steps[unet_index] += 1

